// TOP: top
// TECH: nangate45
// TARGETS: reset_qualified_by_another_flop, dffr_rn_from_sibling_module
// CLUE: the second flop's async reset is (top rn AND the first flop's QN),
// i.e. a reset generated by sequential logic in another submodule.

module ffa (input d, input ck, input rn, output qn);
  DFFR_X1 ff (.D(d), .RN(rn), .CK(ck), .QN(qn));
endmodule

module ffb (input d, input ck, input rn, output q);
  DFFR_X1 ff (.D(d), .RN(rn), .CK(ck), .Q(q));
endmodule

module top (input da, input db, input ck, input rn, output z);
  wire qna, rnb;
  ffa u0 (.d(da), .ck(ck), .rn(rn), .qn(qna));
  AND2_X1 g (.A1(rn), .A2(qna), .ZN(rnb));
  ffb u1 (.d(db), .ck(ck), .rn(rnb), .q(z));
endmodule
